<script>
  // KPR Calculator State & Logic
  let currentPrice = 1450000000;
  let currentDPPercent = 0.10;
  let currentTenorYears = 20;

  function updatePrice(val) {
    currentPrice = parseFloat(val);
    document.getElementById('label-price').innerText = 'Rp ' + Number(currentPrice).toLocaleString('id-ID');
    calculateKPR();
  }

  function setDP(percent, btnEl) {
    currentDPPercent = percent;
    document.querySelectorAll('.dp-btn').forEach(btn => {
      btn.classList.remove('bg-property-traditional-primary', 'text-property-traditional-surface');
      btn.classList.add('bg-property-traditional-surface-container', 'text-property-traditional-on-surface');
    });
    btnEl.classList.remove('bg-property-traditional-surface-container', 'text-property-traditional-on-surface');
    btnEl.classList.add('bg-property-traditional-primary', 'text-property-traditional-surface');
    calculateKPR();
  }

  function updateTenor(val) {
    currentTenorYears = parseInt(val);
    document.getElementById('label-tenor').innerText = currentTenorYears + ' Tahun';
    calculateKPR();
  }

  function calculateKPR() {
    const dpAmount = currentPrice * currentDPPercent;
    const principal = currentPrice - dpAmount;
    const annualRate = parseFloat(document.getElementById('select-bank').value);
    const monthlyRate = annualRate / 12;
    const totalMonths = currentTenorYears * 12;

    // Monthly installment annuity formula: M = P * [r(1+r)^n] / [(1+r)^n - 1]
    const monthlyPayment = principal * (monthlyRate * Math.pow(1 + monthlyRate, totalMonths)) / (Math.pow(1 + monthlyRate, totalMonths) - 1);

    document.getElementById('label-dp-amount').innerText = 'Rp ' + Math.round(dpAmount).toLocaleString('id-ID') + ' (' + (currentDPPercent * 100) + '%)';
    document.getElementById('output-monthly').innerText = 'Rp ' + Math.round(monthlyPayment).toLocaleString('id-ID');
    document.getElementById('output-principal').innerText = 'Rp ' + Math.round(principal).toLocaleString('id-ID');
    document.getElementById('output-dp').innerText = 'Rp ' + Math.round(dpAmount).toLocaleString('id-ID');
  }

  // Unit Catalog Filter Tabs
  function filterUnits(type) {
    document.querySelectorAll('.unit-tab-btn').forEach(btn => {
      if (btn.getAttribute('data-tab') === type) {
        btn.classList.remove('bg-property-traditional-surface-container-high', 'text-property-traditional-on-surface');
        btn.classList.add('bg-property-traditional-primary', 'text-property-traditional-surface');
      } else {
        btn.classList.remove('bg-property-traditional-primary', 'text-property-traditional-surface');
        btn.classList.add('bg-property-traditional-surface-container-high', 'text-property-traditional-on-surface');
      }
    });

    document.querySelectorAll('.unit-card').forEach(card => {
      if (type === 'all' || card.getAttribute('data-type') === type) {
        card.classList.remove('hidden');
      } else {
        card.classList.add('hidden');
